async function saveServerInvoicesHistory(invoices, deletedIds = []) {
  try {
    const deletedSet = getDeletedDocIds();
    (deletedIds || []).forEach(id => { if (id) deletedSet.add(String(id).trim()); });

    const validList = (Array.isArray(invoices) ? invoices : []).filter(inv => {
      if (!inv || !inv.id) return false;
      const cleanId = String(inv.id).trim();
      return !deletedSet.has(cleanId) && !inv._deleted;
    });

    const payload = {
      invoices: validList,
      deletedIds: Array.from(deletedSet)
    };

    const res = await apiFetch('invoices/history', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    return res.ok;
  } catch (e) {
    return false;
  }
}

/**
 * 請求書履歴の双方向スマートマージ同期
 * サーバーとローカルをIDキーで結合し、全ユーザー・全端末の書類履歴を確実に共有・保持
 */
async function syncInvoicesHistoryWithServer() {
  try {
    console.log("【書類履歴同期】サーバーから履歴データ取得開始...");
    const serverInvoices = await fetchServerInvoicesHistory();
    const localInvoices = getHistoryList();
    const deletedSet = getDeletedDocIds();

    const invoiceMap = new Map();
    const serverValidIds = new Set();
    let hasLocalChanges = false;

    // 1. サーバーから取得したデータから削除マーカー(_deleted: true)を検知してローカル削除セットへ反映
    if (Array.isArray(serverInvoices)) {
      serverInvoices.forEach(sinv => {
        if (sinv && sinv.id && sinv._deleted) {
          const cleanId = String(sinv.id).trim();
          recordDeletedDocId(cleanId);
          deletedSet.add(cleanId);
          // 他端末で削除された書類もごみ箱に保管して復元可能にしておく
          addDocToTrash(sinv);
        }
      });
    }

    // 2. ローカル履歴を取り込み（削除済みIDに含まれているものは完全破棄・抹消）
    if (Array.isArray(localInvoices)) {
      localInvoices.forEach(inv => {
        if (inv && inv.id) {
          const cleanId = String(inv.id).trim();
          if (!deletedSet.has(cleanId) && !inv._deleted) {
            invoiceMap.set(cleanId, inv);
          } else {
            console.log(`【書類履歴同期】ローカルに残っていた削除済み伝票(${cleanId})を完全抹消しました`);
            addDocToTrash(inv);
          }
        }
      });
    }

    // 3. サーバー履歴を取り込み（削除済みでなく、_deleted でない有効データのみスマートマージ）
    if (Array.isArray(serverInvoices)) {
      serverInvoices.forEach(sinv => {
        if (sinv && sinv.id) {
          const cleanId = String(sinv.id).trim();
          if (sinv._deleted || deletedSet.has(cleanId)) {
            if (!sinv._deleted && deletedSet.has(cleanId)) {
              hasLocalChanges = true; // ローカル側の削除をサーバーへ伝える必要あり
            }
            // サーバー側またはローカルで削除済みの場合は確実にマップから除去
            invoiceMap.delete(cleanId);
            return;
          }

          serverValidIds.add(cleanId);
          const existing = invoiceMap.get(cleanId);
          if (!existing) {
            invoiceMap.set(cleanId, sinv);
          } else {
            const serverDate = new Date(sinv.updatedAt || sinv.cancelledAt || sinv.issuedAt || sinv.issueDate || 0).getTime();
            const localDate = new Date(existing.updatedAt || existing.cancelledAt || existing.issuedAt || existing.issueDate || 0).getTime();

            // 原則として更新日時（updatedAt）が新しい方を正として採用する
            if (serverDate > localDate) {
              invoiceMap.set(cleanId, sinv);
            } else if (serverDate === localDate && sinv.isCancelled === true && !existing.isCancelled) {
              console.log(`【書類履歴同期】同時刻の確定取消状態を優先マージ: ${cleanId}`);
              invoiceMap.set(cleanId, sinv);
            } else if (localDate > serverDate) {
              console.log(`【書類履歴同期】ローカルの最新状態を保持（サーバーより新しい更新）: ${cleanId}`);
              hasLocalChanges = true;
            }
          }
        }
      });
    } else if (invoiceMap.size > 0) {
      hasLocalChanges = true;
    }

    // ローカルにのみ存在する未送信伝票があるか確認
    invoiceMap.forEach((_, id) => {
      if (!serverValidIds.has(id)) {
        hasLocalChanges = true;
      }
    });

    // 4. 発行日降順にソート & 全伝票シリアル整合性のスマートサニタイズ
    invoiceMap.forEach(sinv => {
      if (sanitizeDocSerialsConsistency(sinv)) hasLocalChanges = true;
      if (sinv.fullDoc && sanitizeDocSerialsConsistency(sinv.fullDoc)) hasLocalChanges = true;
    });

    const mergedList = Array.from(invoiceMap.values()).sort((a, b) => {
      const dateA = a.issueDate || a.updatedAt || '';
      const dateB = b.issueDate || b.updatedAt || '';
      return dateB.localeCompare(dateA);
    });

    // 5. ローカルストレージに保存（サーバーからのPull時はpush-all逆流を起こさない）
    localStorageSetItemOnly(KEYS.HISTORY, JSON.stringify(mergedList));

    // 6. 編集中アクティブ伝票(activeDoc)のゾンビ引きずりチェック
    const activeDoc = loadActiveDoc();
    if (activeDoc && activeDoc.id) {
      const cleanActiveId = String(activeDoc.id).trim();
      if (deletedSet.has(cleanActiveId)) {
        console.log("【書類履歴同期】編集中プレビュー伝票が削除済みだったためクリア:", cleanActiveId);
        localStorage.removeItem(KEYS.ACTIVE_DOC);
        saveServerActiveDoc({}).catch(() => { });
        if (typeof window !== 'undefined' && window.currentDoc && String(window.currentDoc.id).trim() === cleanActiveId) {
          if (typeof window.resetActiveDocToNew === 'function') {
            window.resetActiveDocToNew();
          }
        }
      } else {
        const mergedActive = invoiceMap.get(cleanActiveId);
        if (mergedActive) {
          const mergedTime = new Date(mergedActive.updatedAt || mergedActive.cancelledAt || mergedActive.issuedAt || 0).getTime();
          const activeTime = new Date(activeDoc.updatedAt || activeDoc.cancelledAt || activeDoc.issuedAt || 0).getTime();
          if (mergedTime > activeTime && (Boolean(activeDoc.isIssued) !== Boolean(mergedActive.isIssued) || Boolean(activeDoc.isCancelled) !== Boolean(mergedActive.isCancelled))) {
            activeDoc.isIssued = !!mergedActive.isIssued;
            activeDoc.issuedAt = mergedActive.issuedAt || null;
            activeDoc.isCancelled = !!mergedActive.isCancelled;
            activeDoc.updatedAt = mergedActive.updatedAt || new Date().toISOString();
            localStorage.setItem(KEYS.ACTIVE_DOC, JSON.stringify(activeDoc));
            saveServerActiveDoc(activeDoc).catch(() => { });
            console.log("【書類履歴同期】編集中アクティブ伝票をサーバー最新状態に同期しました:", {
              id: cleanActiveId,
              isIssued: activeDoc.isIssued,
              isCancelled: activeDoc.isCancelled
            });
          }
        }
      }
    }

    // 7. ローカル未送信・変更がある場合のみサーバーへ送信（通常閲覧時の2MB逆流アップロード防止）
    if (hasLocalChanges) {
      await saveServerInvoicesHistory(mergedList, Array.from(deletedSet));
    }
    console.log(`【書類履歴同期】マージ完了: 有効 ${mergedList.length} 件 (削除済み除外: ${deletedSet.size}件, サーバー書込: ${hasLocalChanges})`);

    return mergedList;
  } catch (e) {
    console.warn('Sync invoices history with server failed:', e);
    return getHistoryList();
  }
}
